namespace AkilliKisayol {
 public sealed class PreferencesWindow : Window {
  sealed class AppChoice {public string Path {get;set;}public string Name {get{return string.IsNullOrEmpty(Path)?"No preference — resolve from prompt":BrowserSupport.DisplayName(Path);}}}
  readonly UserPreferences draft;readonly ComboBox browser=new ComboBox(),media=new ComboBox(),app=new ComboBox();readonly TextBox match=new TextBox();readonly ListBox rules=new ListBox{Height=180};readonly CheckBox learn=new CheckBox{Content="Remember application preferences from saved connection assignments"};readonly TextBlock feedback=Theme.Text("",12,"Muted");readonly Func<UserPreferences,bool> save;
  public PreferencesWindow(UserPreferences preferences,IEnumerable<string> applications,Func<UserPreferences,bool> persist){
   draft=preferences.Copy();save=persist;Title="Application preferences";Style=(Style)Application.Current.FindResource(typeof(Window));Width=800;Height=760;MinHeight=620;MinWidth=650;WindowStartupLocation=WindowStartupLocation.CenterOwner;Brand.Fit(this);
   var dock=new DockPanel{Margin=new Thickness(26)};Content=dock;var footer=new StackPanel();footer.Children.Add(feedback);var buttons=new WrapPanel{HorizontalAlignment=HorizontalAlignment.Right,Margin=new Thickness(0,12,0,0)};buttons.Children.Add(Theme.Button("Cancel",()=>DialogResult=false));buttons.Children.Add(Theme.Button("Save preferences",Commit,true));footer.Children.Add(buttons);DockPanel.SetDock(footer,Dock.Bottom);dock.Children.Add(footer);
   var form=new StackPanel();dock.Children.Add(new ScrollViewer{Content=form,VerticalScrollBarVisibility=ScrollBarVisibility.Auto});form.Children.Add(Theme.Text("Remember your selection",25));form.Children.Add(Theme.Text("These preferences are added as defaults to subsequent prompts. The application you typed in the prompt or the target you selected always comes first.",13,"Muted"));
   var paths=applications.Concat(PreferenceMemory.Paths(draft)).Where(p=>!string.IsNullOrWhiteSpace(p)).Distinct(StringComparer.OrdinalIgnoreCase).OrderBy(BrowserSupport.DisplayName).ToArray();foreach(var combo in new[]{browser,media,app}){combo.DisplayMemberPath="Name";combo.SelectedValuePath="Path";combo.ItemsSource=new[]{new AppChoice{Path=""}}.Concat(paths.Select(p=>new AppChoice{Path=p})).ToList();combo.SelectedIndex=0;}
   Label(form,"Preferred application for Web connections");form.Children.Add(browser);browser.SelectedValue=draft.Browser??"";Label(form,"Preferred application for music/playlist");form.Children.Add(media);media.SelectedValue=draft.MediaApp??"";learn.IsChecked=draft.LearnOnSave;form.Children.Add(learn);
   Label(form,"Custom preference based on domain name or expression");match.ToolTip="Example: open.spotify.com or documentation";form.Children.Add(match);app.Margin=new Thickness(0,8,0,8);form.Children.Add(app);var bar=new WrapPanel();bar.Children.Add(Theme.Button("Add / update preference",AddRule));bar.Children.Add(Theme.Button("Remove selected option",()=>{if(rules.SelectedIndex>=0){draft.Rules.RemoveAt(rules.SelectedIndex);Refresh();}}));form.Children.Add(bar);form.Children.Add(rules);rules.SelectionChanged+=(s,e)=>{if(rules.SelectedIndex>=0&&rules.SelectedIndex<draft.Rules.Count){var item=draft.Rules[rules.SelectedIndex];match.Text=item.Match;app.SelectedValue=item.AppPath;}};Refresh();
  }
  static void Label(StackPanel panel,string text){var label=Theme.Text(text,13);label.Margin=new Thickness(0,16,0,8);panel.Children.Add(label);}
  void Refresh(){rules.ItemsSource=draft.Rules.Select(r=>r.Match+" → "+BrowserSupport.DisplayName(r.AppPath)+(File.Exists(r.AppPath)?"":" • file not found")).ToList();}
  void AddRule(){string value=match.Text.Trim(),path=app.SelectedValue as string;if(value.Length==0||value.Length>200||string.IsNullOrEmpty(path)){feedback.Text="Select the matching domain/regex and target application.";return;}var old=draft.Rules.FirstOrDefault(r=>r.Match.Equals(value,StringComparison.OrdinalIgnoreCase));if(old==null)draft.Rules.Add(new AppPreference{Match=value,AppPath=path});else old.AppPath=path;Refresh();feedback.Text="Added to preferences list. Save and apply.";}
  void Commit(){draft.Browser=browser.SelectedValue as string??"";draft.MediaApp=media.SelectedValue as string??"";draft.LearnOnSave=learn.IsChecked==true;if(save(draft.Copy()))DialogResult=true;else feedback.Text="Preference could not be saved; previous selections are preserved.";}
  internal UserPreferences DraftForTest {get{return draft;}}
  internal void SaveForTest(string path){browser.SelectedValue=path;Commit();}
 }
 public sealed class ProfileAssignment {
  public string Id {get;set;}public string Name {get;set;}public string Combo {get;set;}public string ProfileId {get;set;}
 }
 public sealed class ProfilesWindow : Window {
  readonly ObservableCollection<ShortcutProfile> profiles,choices;readonly List<ProfileAssignment> assignments;readonly DataGrid profileGrid=new DataGrid{Height=235},bindingGrid=new DataGrid{MinHeight=180};readonly TextBox newName=new TextBox{Width=230};readonly TextBlock feedback=Theme.Text("",12,"Muted");readonly Func<List<ShortcutProfile>,List<ProfileAssignment>,bool> save;
  public ProfilesWindow(State state,Func<List<ShortcutProfile>,List<ProfileAssignment>,bool> persist){
   save=persist;profiles=new ObservableCollection<ShortcutProfile>(state.Profiles.Select(p=>p.Copy()));choices=new ObservableCollection<ShortcutProfile>(new[]{new ShortcutProfile{Id="",Name="All profiles"}}.Concat(profiles));assignments=state.Bindings.Select(b=>new ProfileAssignment{Id=b.Id,Name=b.Name,Combo=b.Combo,ProfileId=b.ProfileId??""}).ToList();
   Title="Shortcut profiles";Style=(Style)Application.Current.FindResource(typeof(Window));Width=930;Height=800;MinWidth=740;MinHeight=650;WindowStartupLocation=WindowStartupLocation.CenterOwner;Brand.Fit(this);
   var dock=new DockPanel{Margin=new Thickness(25)};Content=dock;var footer=new StackPanel();footer.Children.Add(feedback);var buttons=new WrapPanel{HorizontalAlignment=HorizontalAlignment.Right,Margin=new Thickness(0,12,0,0)};buttons.Children.Add(Theme.Button("Cancel",()=>DialogResult=false));buttons.Children.Add(Theme.Button("Save profiles",Commit,true));footer.Children.Add(buttons);DockPanel.SetDock(footer,Dock.Bottom);dock.Children.Add(footer);
   var form=new StackPanel();dock.Children.Add(new ScrollViewer{Content=form,VerticalScrollBarVisibility=ScrollBarVisibility.Auto});form.Children.Add(Theme.Text("Task, game and work schedule",25));form.Children.Add(Theme.Text("Change groups by selecting the profile in the bottom left. Assignments across all profiles are shared; profile-specific assignments take precedence within the same key and scope. External source files are not changed during profile switching.",13,"Muted"));
   profileGrid.IsReadOnly=false;profileGrid.AutoGenerateColumns=false;profileGrid.Columns.Add(new DataGridTextColumn{Header="Profile name",Binding=new System.Windows.Data.Binding("Name"),Width=new DataGridLength(1,DataGridLengthUnitType.Star)});profileGrid.Columns.Add(new DataGridCheckBoxColumn{Header="Disable general write keys without modifiers",Binding=new System.Windows.Data.Binding("SuppressTypingKeys"),Width=new DataGridLength(1.5,DataGridLengthUnitType.Star)});profileGrid.ItemsSource=profiles;profileGrid.Margin=new Thickness(0,15,0,12);form.Children.Add(profileGrid);
   var bar=new WrapPanel();bar.Children.Add(newName);bar.Children.Add(Theme.Button("Add profile",AddProfile));form.Children.Add(bar);form.Children.Add(Theme.Text("Assignments profile",19));
   bindingGrid.IsReadOnly=false;bindingGrid.AutoGenerateColumns=false;bindingGrid.Columns.Add(new DataGridTextColumn{Header="Shortcut",Binding=new System.Windows.Data.Binding("Name"),IsReadOnly=true,Width=new DataGridLength(1.6,DataGridLengthUnitType.Star)});bindingGrid.Columns.Add(new DataGridTextColumn{Header="Key",Binding=new System.Windows.Data.Binding("Combo"),IsReadOnly=true,Width=new DataGridLength(1,DataGridLengthUnitType.Star)});bindingGrid.Columns.Add(new DataGridComboBoxColumn{Header="Profile",ItemsSource=choices,DisplayMemberPath="Name",SelectedValuePath="Id",SelectedValueBinding=new System.Windows.Data.Binding("ProfileId"),Width=new DataGridLength(1.2,DataGridLengthUnitType.Star)});bindingGrid.ItemsSource=assignments;bindingGrid.Margin=new Thickness(0,10,0,0);form.Children.Add(bindingGrid);
  }
  void AddProfile(){string name=newName.Text.Trim();if(name.Length==0||name.Length>50||profiles.Any(p=>p.Name.Equals(name,StringComparison.CurrentCultureIgnoreCase))){feedback.Text="Enter a different and maximum 50-character profile name.";return;}var profile=new ShortcutProfile{Id=Guid.NewGuid().ToString("N"),Name=name};profiles.Add(profile);choices.Add(profile);newName.Clear();}
  void Commit(){profileGrid.CommitEdit(DataGridEditingUnit.Cell,true);profileGrid.CommitEdit(DataGridEditingUnit.Row,true);bindingGrid.CommitEdit(DataGridEditingUnit.Cell,true);bindingGrid.CommitEdit(DataGridEditingUnit.Row,true);if(profiles.Any(p=>string.IsNullOrWhiteSpace(p.Name)||p.Name.Length>50)||profiles.GroupBy(p=>p.Name.Trim(),StringComparer.CurrentCultureIgnoreCase).Any(g=>g.Count()>1)){feedback.Text="Profile names cannot be empty or identical.";return;}if(save(profiles.Select(p=>p.Copy()).ToList(),assignments))DialogResult=true;else feedback.Text="Could not be saved. Check for key conflicts or recording errors in the same profile/scope.";}
  internal int ProfileCountForTest {get{return profiles.Count;}}
  internal void SaveForTest(string bindingId,string profileId){assignments.First(a=>a.Id==bindingId).ProfileId=profileId;Commit();}
 }
}
